import test from "node:test";
import assert from "node:assert/strict";
import {canonicalTWAP} from "../twap.mjs";
const now=Date.parse("2026-10-12T12:00:00Z"),scale=10n**18n;
const policy={approved:true,version:"FIXTURE-TWAP-1",poolId:"fixture-pool",baseAssetId:"RIO",quoteAssetId:"RUSD",chainId:"fixture-chain",windowSeconds:600,maxGapSeconds:600,maxAgeSeconds:600,minimumObservations:2};
function point(age,price,index){return {verified:true,timestamp:new Date(now-age).toISOString(),poolId:policy.poolId,baseAssetId:policy.baseAssetId,quoteAssetId:policy.quoteAssetId,chainId:policy.chainId,priceNumerator:String(price),priceDenominator:"1",height:String(index+1),blockHash:"fixture-block-"+index,reference:"fixture:"+index};}
test("irregular observations produce a genuine time-weighted value rather than a trade mean",()=>{const rows=[point(600000,1,0),point(500000,5,1),point(100000,7,2)];const result=canonicalTWAP(policy,rows,now);assert.equal(result.available,true);assert.equal(result.coverageMs,600000);assert.equal(result.priceScaled,(scale*2800000n/600000n).toString());assert.notEqual(result.priceScaled,(scale*13n/3n).toString());});
test("empty, missing carry-in, stale, gapped, future and manipulated observations fail closed",()=>{for(const rows of [[],[point(500000,1,0),point(100000,5,1)],[point(600000,1,0),point(599000,5,1)],[point(600000,1,0),point(-1,5,1)],[point(600000,1,0),{...point(100000,5,1),priceDenominator:"0"}],[point(600000,1,0),{...point(100000,5,1),poolId:"attacker"}]]){const result=canonicalTWAP({...policy,maxGapSeconds:300,maxAgeSeconds:60},rows,now);assert.equal(result.available,false);assert.equal(result.priceScaled,null);}});
test("out-of-window observations cannot replace required coverage and conflicting duplicates reject",()=>{const rows=[point(600000,1,0),point(300000,3,1)];const r=canonicalTWAP(policy,[point(900000,99,4),...rows],now);assert.equal(r.priceScaled,(2n*scale).toString());assert.equal(canonicalTWAP(policy,[...rows,{...rows[1],priceNumerator:"9"}],now).available,false);assert.equal(canonicalTWAP({...policy,approved:false},rows,now).available,false);});
